import java.io.File;
import java.io.IOException;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a unique {@link File} inside {@code dir} using {@code name}.
     * <p>
     * The method protects against directory‑traversal attacks by resolving the
     * canonical path of the target file and ensuring it resides within the
     * supplied {@code dir}. Any attempt to escape the directory results in an
     * {@link IllegalArgumentException}. Query parameters are stripped from
     * {@code name} before processing.
     *
     * @param dir  the base directory where the file should be created; must not be {@code null}
     * @param name the desired file name; may contain query parameters which are removed
     * @return a {@link File} instance that does not yet exist on disk
     * @throws NullPointerException     if {@code dir} or {@code name} is {@code null}
     * @throws IllegalArgumentException if the resolved file would be outside {@code dir}
     * @throws IllegalStateException    if canonical path resolution fails
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new NullPointerException("Directory cannot be null");
        }
        if (name == null) {
            throw new NullPointerException("Name cannot be null");
        }

        // Strip query parameters (e.g., "file.txt?foo=bar")
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Construct the candidate file
        File file = new File(dir, name);

        // Resolve canonical paths to guard against traversal
        try {
            String canonicalDir = dir.getCanonicalPath();
            String canonicalFile = file.getCanonicalPath();

            // Ensure the file is inside the target directory
            if (!canonicalFile.startsWith(canonicalDir + File.separator)) {
                throw new IllegalArgumentException(
                        "Attempt to write outside the target directory: " + canonicalFile);
            }
        } catch (IOException e) {
            throw new IllegalStateException("Failed to resolve canonical paths", e);
        }

        // Determine prefix/suffix for unique naming
        int dot = name.indexOf('.');
        String prefix = dot < 0 ? name : name.substring(0, dot);
        String suffix = dot < 0 ? "" : name.substring(dot);

        // Append numeric suffixes until a non‑existing file is found
        int index = 2;
        while (file.exists()) {
            file = new File(dir, prefix + "-" + index++ + suffix);
        }

        // Ensure parent directories exist
        File parent = file.getParentFile();
        if (parent != null && !parent.mkdirs() && !parent.isDirectory()) {
            throw new IllegalStateException("Failed to create directories: " + parent);
        }

        return file;
    }

    // other methods
}
