                int count = n & 0x7F; // number of repetitions (max 127)

                // Write up to the remaining space in the output buffer
                for (int i = 0; i < count && position < total; i++) {
                    out[position++] = (byte) value;
                }
            } else { // literal run of n bytes
                for (int i = 0; i < n && position < total; i++) {
                    int b = in.read();
                    if (b == -1) {
                        throw new EOFException("Unexpected end of stream while reading literal data");
                    }
                    out[position++] = (byte) b;
                }
            }
