import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import org.apache.commons.compress.archivers.ArchiveEntry;

public class Expander {

    // other methods

    /**
     * Safely expands the contents of an archive into {@code targetDirectory}.
     *
     * <p>All entry names are validated against the canonical form of the target directory to
     * prevent path‑traversal attacks. Absolute paths, empty names, and names that resolve
     * outside the target directory are rejected. Directory creation is performed using
     * {@link Files#createDirectories} to avoid race conditions.</p>
     */
    private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
        // Resolve the canonical path of the target directory once.
        Path canonicalTargetDir = targetDirectory.getCanonicalFile().toPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            String entryName = nextEntry.getName();

            // Skip entries with no name – they are harmless but could cause confusion.
            if (entryName == null || entryName.isEmpty()) {
                nextEntry = supplier.getNextReadableEntry();
                continue;
            }

            // Reject absolute paths – they would ignore the target directory entirely.
            if (new File(entryName).isAbsolute()) {
                throw new IOException("Archive entry has an absolute path: " + entryName);
            }

            // Resolve the entry against the target directory and obtain its canonical form.
            File entryFile = new File(targetDirectory, entryName);
            Path canonicalEntryPath = entryFile.getCanonicalFile().toPath();

            // Ensure the canonical entry path is still within the target directory.
            if (!canonicalEntryPath.startsWith(canonicalTargetDir)) {
                throw new IOException("Archive entry would be written outside the target directory: "
                        + entryName);
            }

            if (nextEntry.isDirectory()) {
                // Create the directory if it does not exist.
                if (!entryFile.isDirectory() && !entryFile.mkdirs()) {
                    throw new IOException("Failed to create directory: " + entryFile);
                }
            } else {
                // Ensure the parent directory exists.
                File parent = entryFile.getParentFile();
                if (parent != null && !parent.isDirectory() && !parent.mkdirs()) {
                    throw new IOException("Failed to create parent directory: " + parent);
                }

                // Write the file data.
                try (OutputStream out = Files.newOutputStream(entryFile.toPath())) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

    // other methods

}
