import org.apache.commons.io.IOUtils;
import org.cloudfoundry.identity.uaa.scim.ScimUser;
import org.cloudfoundry.identity.uaa.scim.ScimUserProvisioning;
import org.cloudfoundry.identity.uaa.scim.exception.ScimResourceNotFoundException;
import org.cloudfoundry.identity.uaa.util.JsonUtils;
import org.cloudfoundry.identity.uaa.util.UaaUrlUtils;
import org.cloudfoundry.identity.uaa.zone.IdentityZoneHolder;

import javax.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.security.Principal;
import java.util.Objects;
import java.util.logging.Level;
import java.util.logging.Logger;

/**
 * Utility class that determines whether a self‑update request for a SCIM user
 * is allowed. The original implementation only compared the contents of the
 * request against the stored user record, which meant that an attacker could
 * change the email address of any user by simply submitting a request with
 * that email.  The patched implementation now verifies that the caller is
 * actually the owner of the account being updated.
 */
public class ScimUserSelfUpdateAllowed {

    private static final Logger LOGGER = Logger.getLogger(ScimUserSelfUpdateAllowed.class.getName());

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private final ScimUserProvisioning scimUserProvisioning;

    public ScimUserSelfUpdateAllowed(ScimUserProvisioning scimUserProvisioning) {
        this.scimUserProvisioning = Objects.requireNonNull(scimUserProvisioning, "scimUserProvisioning must not be null");
    }

    /**
     * Returns {@code true} if the incoming request is allowed to update the
     * specified user.  The method performs the following checks:
     *
     * <ul>
     *   <li>The authenticated user ID extracted from the request must match
     *       the ID of the user being updated.</li>
     *   <li>The ID supplied in the URL path must match the ID in the request
     *       body.</li>
     *   <li>All other fields are compared against the stored record to
     *       prevent accidental or malicious changes.</li>
     * </ul>
     *
     * @param request the HTTP request containing the update payload
     * @return {@code true} if the update is permitted, {@code false} otherwise
     * @throws IOException if reading the request body fails
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        // Read and parse the request body
        String requestBody = IOUtils.toString(request.getReader());
        ScimUser scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);

        // Extract the user ID from the URL path
        String pathId = UaaUrlUtils.extractPathVariableFromUrl(USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request));

        // Retrieve the user record from the database
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(pathId, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist, allow the operation to proceed
            // (the caller will receive a 404 later)
            return true;
        }

        // Verify that the authenticated user is the owner of the account
        String authenticatedUserId = getAuthenticatedUserId(request);
        if (!Objects.equals(authenticatedUserId, scimUserFromDb.getId())) {
            LOGGER.log(Level.WARNING,
                    "Unauthorized update attempt: authenticated user {0} tried to modify user {1}",
                    new Object[]{authenticatedUserId, scimUserFromDb.getId()});
            return false;
        }

        // Ensure the ID in the request body matches the path ID
        if (!Objects.equals(scimUserFromRequest.getId(), pathId)) {
            LOGGER.log(Level.WARNING,
                    "Mismatched user ID in request body: body={0}, path={1}",
                    new Object[]{scimUserFromRequest.getId(), pathId});
            return false;
        }

        // Compare all relevant fields to detect unauthorized changes
        if (!Objects.equals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getUserName(), scimUserFromRequest.getUserName())) {
            return false;
        }
        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }
        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getOrigin(), scimUserFromRequest.getOrigin())) {
            return false;
        }

        return true;
    }

    /**
     * Attempts to determine the authenticated user ID from the request.
     * <p>
     * The method first checks the {@link Principal} associated with the request.
     * If that is unavailable, it falls back to the {@code X-Authenticated-User-Id}
     * header, which is commonly used in UAA deployments.  If neither source
     * yields a value, {@code null} is returned.
     *
     * @param request the HTTP request
     * @return the authenticated user ID, or {@code null} if it cannot be determined
     */
    private String getAuthenticatedUserId(HttpServletRequest request) {
        Principal principal = request.getUserPrincipal();
        if (principal != null && principal.getName() != null) {
            return principal.getName();
        }
        // Fallback header used by some UAA setups
        String headerId = request.getHeader("X-Authenticated-User-Id");
        return (headerId != null && !headerId.isEmpty()) ? headerId : null;
    }
}
